mapper.select:
SELECT *
FROM plt_collection_task
WHERE tenant_id = #{tenantId}
  AND platform_task_id = #{platformTaskId}
  AND deleted = b'0'

mapper.update:
UPDATE plt_collection_task
SET status = #{update.status},
    technical_stage = #{update.technicalStage},
    external_task_id = #{update.externalTaskId},
    external_status = #{update.externalStatus},
    failure_category = #{update.failureCategory}
WHERE tenant_id = #{update.tenantId}
  AND platform_task_id = #{update.platformTaskId}
  AND technical_stage = #{update.expectedTechnicalStage}
  AND deleted = b'0'
